from threetears.evals import Eval

from recur import Series, invites

def send(case):
    """The UTC invites the calendar server gets for the series."""
    return {"invites": invites(Series.from_json(case))}


def matches_old_calendar(case, out):
    """Every invite is the one the old calendar sent."""
    return out["invites"] == case["old_calendar"]

series = Eval("data/series.jsonl", runner=send, grader=[matches_old_calendar], k=1)
